-- PRUEBAS para TAB_LOTES y TAB_ANIMALES
-- SE EJECUTAN DENTRO DE UNA TRANSACCION Y AL FINAL SE HACE ROLLBACK PARA NO DEJAR DATOS DE PRUEBA
-- LOS UUID DE PRUEBA SON FIJOS PARA PODER LEERLOS: ...a = ANIMALES, ...1 = LOTES
BEGIN;

--FINCA DE PRUEBA CON DUEÑO Y VAQUERO
SELECT FUN_CREAR_FINCA_JSON('Finca Prueba', 'San Gil', NULL, NULL, NULL, 'PRU-DUENO', 'Dueño Prueba') ->> 'CODIGO' AS FINCA_200;
CREATE FUNCTION pg_temp.FINCA() RETURNS INTEGER AS $$ SELECT ID_FINCA FROM TAB_FINCAS WHERE NOM_FINCA = 'Finca Prueba' $$ LANGUAGE sql;
SELECT FUN_AGREGAR_PERSONA_FINCA_JSON(pg_temp.FINCA(), 'PRU-VAQUERO', 'Vaquero Prueba', 'VAQUERO', 'PRU-DUENO') ->> 'CODIGO' AS VAQUERO_200;

SELECT 'PRUEBA 1.1: Lotes. Crear 200 (vaquero puede); reintento con el mismo UUID 200 YA_EXISTIA true; nombre repetido 400; vaquero no renombra 400' as PRUEBA;
SELECT FUN_CREAR_LOTE_JSON('00000000-0000-0000-0000-000000000001', pg_temp.FINCA(), 'Ordeño', 'PRU-VAQUERO') ->> 'CODIGO' AS CREAR_200,
       FUN_CREAR_LOTE_JSON('00000000-0000-0000-0000-000000000001', pg_temp.FINCA(), 'Ordeño', 'PRU-VAQUERO') -> 'DATOS' ->> 'YA_EXISTIA' AS REINTENTO_TRUE,
       FUN_CREAR_LOTE_JSON('00000000-0000-0000-0000-000000000002', pg_temp.FINCA(), 'ORDEÑO', 'PRU-DUENO') ->> 'CODIGO' AS REPETIDO_400,
       FUN_ACTUALIZAR_LOTE_JSON('00000000-0000-0000-0000-000000000001', pg_temp.FINCA(), 'Vacas de ordeño', 'PRU-VAQUERO') ->> 'CODIGO' AS VAQUERO_RENOMBRA_400;
SELECT FUN_CREAR_LOTE_JSON('00000000-0000-0000-0000-000000000002', pg_temp.FINCA(), 'Levante', 'PRU-DUENO') ->> 'CODIGO' AS LEVANTE_200,
       FUN_OBTENER_LOTES_JSON(pg_temp.FINCA(), 'PRU-VAQUERO') -> 'DATOS' -> 0 ->> 'NOM_LOTE' AS LEVANTE;

SELECT 'PRUEBA 2.1: Animales. Vaca comprada de 5 años (200), toro de 4 años (200), novilla hija de la vaca (200, vaquero); reintento YA_EXISTIA' as PRUEBA;
SELECT FUN_CREAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000a', pg_temp.FINCA(), '00000000-0000-0000-0000-000000000001', 2, '23', 'Lucero', 'H',
           (CURRENT_DATE - INTERVAL '5 years')::DATE, 'SI', NULL, NULL, NULL, 'COMPRADO', (CURRENT_DATE - INTERVAL '2 years')::DATE, 'PRU-DUENO') ->> 'CODIGO' AS VACA_200,
       FUN_CREAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000b', pg_temp.FINCA(), NULL, 1, 't-1', 'Tormenta', 'M',
           (CURRENT_DATE - INTERVAL '4 years')::DATE, 'NO', NULL, NULL, NULL, 'COMPRADO', (CURRENT_DATE - INTERVAL '1 year')::DATE, 'PRU-DUENO') ->> 'CODIGO' AS TORO_200,
       FUN_CREAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000c', pg_temp.FINCA(), '00000000-0000-0000-0000-000000000002', 13, '41', NULL, 'H',
           (CURRENT_DATE - INTERVAL '18 months')::DATE, 'NO', '00000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000b', NULL, 'NACIDO', NULL, 'PRU-VAQUERO') ->> 'CODIGO' AS NOVILLA_200;
SELECT FUN_CREAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000c', pg_temp.FINCA(), NULL, NULL, '41', NULL, 'H', CURRENT_DATE, 'NO', NULL, NULL, NULL, 'NACIDO', NULL, 'PRU-VAQUERO') -> 'DATOS' ->> 'YA_EXISTIA' AS REINTENTO_TRUE;

SELECT 'PRUEBA 2.2: Datos guardados. Chapeta en mayúsculas T-1; la novilla nacida ingresa el día que nace; categorías VACA? NO: la comprada sin partos es NOVILLA, el toro TORO, la hija NOVILLA' as PRUEBA;
SELECT CHAPETA_ANIMAL AS T_1, FUN_CATEGORIA_ANIMAL(ID_ANIMAL) AS TORO FROM TAB_ANIMALES WHERE UUID_ANIMAL = '00000000-0000-0000-0000-00000000000b';
SELECT FECHA_INGRESO_ANIMAL = FECHA_NACIMIENTO AS INGRESO_AL_NACER_TRUE, FUN_CATEGORIA_ANIMAL(ID_ANIMAL) AS NOVILLA, FUN_ETIQUETA_ANIMAL(ID_ANIMAL) AS ETIQUETA
FROM TAB_ANIMALES WHERE UUID_ANIMAL = '00000000-0000-0000-0000-00000000000c';
SELECT FUN_CATEGORIA_ANIMAL(ID_ANIMAL) AS NOVILLA_SIN_PARTOS FROM TAB_ANIMALES WHERE UUID_ANIMAL = '00000000-0000-0000-0000-00000000000a';

SELECT 'PRUEBA 2.3: Validaciones al crear. TODAS 400' as PRUEBA;
SELECT T.CASO, R ->> 'CODIGO' AS CODIGO, R ->> 'MENSAJE' AS MENSAJE
FROM (VALUES
    ('CHAPETA REPETIDA', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '23', NULL, 'H', '2024-01-01', 'NO', NULL, NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO')),
    ('SIN CHAPETA NI NOMBRE', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, ' ', ' ', 'H', '2024-01-01', 'NO', NULL, NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO')),
    ('SEXO MALO', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'X', '2024-01-01', 'NO', NULL, NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO')),
    ('NACE EN EL FUTURO', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'H', CURRENT_DATE + 3, 'NO', NULL, NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO')),
    ('MADRE MACHO', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'H', CURRENT_DATE - 10, 'NO', '00000000-0000-0000-0000-00000000000b', NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO')),
    ('MADRE MUY JOVEN', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'H', (CURRENT_DATE - INTERVAL '6 months')::DATE, 'NO', '00000000-0000-0000-0000-00000000000c', NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO')),
    ('PADRE HEMBRA', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'H', CURRENT_DATE - 10, 'NO', NULL, '00000000-0000-0000-0000-00000000000a', NULL, 'NACIDO', NULL, 'PRU-DUENO')),
    ('PADRE DOBLE', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'H', CURRENT_DATE - 10, 'NO', NULL, '00000000-0000-0000-0000-00000000000b', 'Pajilla X', 'NACIDO', NULL, 'PRU-DUENO')),
    ('MADRE DE OTRA FINCA', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'H', CURRENT_DATE - 10, 'NO', gen_random_uuid(), NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO')),
    ('COMPRADO SIN LLEGADA', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'H', '2024-01-01', 'NO', NULL, NULL, NULL, 'COMPRADO', NULL, 'PRU-DUENO')),
    ('EXTRAÑO', FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '99', NULL, 'H', '2024-01-01', 'NO', NULL, NULL, NULL, 'NACIDO', NULL, 'PRU-EXTRANO'))
) AS T(CASO, R);

SELECT 'PRUEBA 3.1: Editar. Vaquero 400; dueño cambia nombre y lote 200; chapeta de otro 400' as PRUEBA;
SELECT FUN_ACTUALIZAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000c', pg_temp.FINCA(), NULL, 13, '41', 'Canela', 'H', (CURRENT_DATE - INTERVAL '18 months')::DATE, 'NO',
           '00000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000b', NULL, 'NACIDO', NULL, 'PRU-VAQUERO') ->> 'CODIGO' AS VAQUERO_400,
       FUN_ACTUALIZAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000c', pg_temp.FINCA(), '00000000-0000-0000-0000-000000000001', 13, '41', 'Canela', 'H', (CURRENT_DATE - INTERVAL '18 months')::DATE, 'NO',
           '00000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000b', NULL, 'NACIDO', NULL, 'PRU-DUENO') ->> 'CODIGO' AS DUENIO_200,
       FUN_ACTUALIZAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000c', pg_temp.FINCA(), NULL, 13, '23', 'Canela', 'H', (CURRENT_DATE - INTERVAL '18 months')::DATE, 'NO',
           NULL, NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO') ->> 'CODIGO' AS CHAPETA_DE_OTRO_400;
SELECT FUN_OBTENER_ANIMAL_POR_UUID_JSON(pg_temp.FINCA(), '00000000-0000-0000-0000-00000000000c', 'PRU-VAQUERO') -> 'DATOS' -> 'ANIMAL' ->> 'NOM_LOTE' AS ORDENO,
       FUN_OBTENER_ANIMAL_POR_UUID_JSON(pg_temp.FINCA(), '00000000-0000-0000-0000-00000000000a', 'PRU-VAQUERO') -> 'DATOS' -> 'CRIAS' -> 0 ->> 'CHAPETA_ANIMAL' AS CRIA_41;

SELECT 'PRUEBA 4.1: Anular. La vaca es madre: 400; la novilla sin eventos: 200, y otra vez 200 YA_EXISTIA; ya no sale en la lista (2 animales); su chapeta queda libre (200)' as PRUEBA;
SELECT FUN_ANULAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000a', pg_temp.FINCA(), 'PRU-DUENO') ->> 'CODIGO' AS ES_MADRE_400,
       FUN_ANULAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000c', pg_temp.FINCA(), 'PRU-VAQUERO') ->> 'CODIGO' AS VAQUERO_400;
SELECT FUN_ANULAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000c', pg_temp.FINCA(), 'PRU-DUENO') ->> 'CODIGO' AS ANULAR_200;
SELECT FUN_ANULAR_ANIMAL_JSON('00000000-0000-0000-0000-00000000000c', pg_temp.FINCA(), 'PRU-DUENO') -> 'DATOS' ->> 'YA_EXISTIA' AS OTRA_VEZ_TRUE,
       json_array_length(FUN_OBTENER_ANIMALES_JSON(pg_temp.FINCA(), 'ACTIVO', 'PRU-VAQUERO') -> 'DATOS') AS DOS_ANIMALES,
       FUN_CREAR_ANIMAL_JSON(gen_random_uuid(), pg_temp.FINCA(), NULL, NULL, '41', NULL, 'M', CURRENT_DATE - 30, 'NO', NULL, NULL, NULL, 'NACIDO', NULL, 'PRU-DUENO') ->> 'CODIGO' AS CHAPETA_LIBRE_200;

SELECT 'PRUEBA 5.1: Anular lote. Sus animales quedan sin lote (200); la vaca ya no tiene lote' as PRUEBA;
SELECT FUN_ANULAR_LOTE_JSON('00000000-0000-0000-0000-000000000001', pg_temp.FINCA(), 'PRU-DUENO') ->> 'CODIGO' AS ANULAR_LOTE_200;
SELECT ID_LOTE IS NULL AS SIN_LOTE_TRUE FROM TAB_ANIMALES WHERE UUID_ANIMAL = '00000000-0000-0000-0000-00000000000a';

SELECT 'PRUEBA 6.1: Línea de tiempo de la vaca recién creada: 200 con un solo evento (llegó comprada); de otra finca 400' as PRUEBA;
SELECT FUN_OBTENER_LINEA_TIEMPO_JSON(pg_temp.FINCA(), '00000000-0000-0000-0000-00000000000a', 'PRU-VAQUERO') -> 'DATOS' -> 0 ->> 'DESCRIPCION_EVENTO' AS LLEGO_COMPRADA,
       FUN_OBTENER_LINEA_TIEMPO_JSON(pg_temp.FINCA(), '00000000-0000-0000-0000-00000000000a', 'PRU-EXTRANO') ->> 'CODIGO' AS EXTRANO_400;

ROLLBACK;
